from functools import lru_cache
G=['.##.##.','######.','.##.#..','..###..','.......','.......','.......']
S={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x=='#'}
placements=[]
for r in range(6):
 for c in range(6):
  sq={(r+i,c+j) for i in range(2) for j in range(2)}
  if sq<=S: placements.append(('sq',sq))
  for miss in [(0,0),(0,1),(1,0),(1,1)]:
   p={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+miss[0],c+miss[1])}
   if p<=S: placements.append((f'L{miss}',p))
@lru_cache(None)
def solve(rem):
 rem=set(rem)
 if not rem:return [[]]
 cell=min(rem)
 out=[]
 for typ,p in placements:
  if cell in p and p<=rem:
   for rest in solve(tuple(sorted(rem-p))):out.append([(typ,p)]+rest)
 return out
sol=solve(tuple(sorted(S)))
print('solutions',len(sol))
for ss in sol[:8]:
 print([(t,sorted(p)) for t,p in ss])
